CREATE OR REPLACE FUNCTION public.admin_archive_client_financial_history(p_cliente_id uuid, p_reason text DEFAULT 'client_deletion'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_finance integer := 0;
  v_contracts integer := 0;
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  if not exists (select 1 from public.clientes where id = p_cliente_id) then
    raise exception 'Cliente não encontrado';
  end if;

  v_finance := private.archive_financial_rows(
    p_cliente_id,
    null,
    null,
    coalesce(nullif(btrim(p_reason), ''), 'client_deletion'),
    auth.uid()
  );
  v_contracts := private.archive_client_contracts(
    p_cliente_id,
    coalesce(nullif(btrim(p_reason), ''), 'client_deletion'),
    auth.uid()
  );

  return jsonb_build_object(
    'financialEntries', v_finance,
    'contracts', v_contracts,
    'totalArchived', v_finance + v_contracts
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_assign_commercial_contract_number(p_record_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_number text;
BEGIN
  IF NOT public.is_portal_admin() THEN RAISE EXCEPTION 'Acesso administrativo necessário'; END IF;
  SELECT contract_number INTO v_number FROM public.commercial_records WHERE id=p_record_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro comercial não encontrado'; END IF;
  IF v_number IS NULL OR btrim(v_number)='' THEN
    v_number := public.admin_next_commercial_number('CON');
    UPDATE public.commercial_records SET contract_number=v_number, updated_at=now() WHERE id=p_record_id;
  END IF;
  RETURN v_number;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_confirm_document_rule_review(p_review_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_review public.document_rule_reviews%rowtype;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessario'; end if;
  select * into v_review
  from public.document_rule_reviews
  where id=p_review_id and status='pending';
  if not found then return false; end if;

  update public.document_rule_reviews
  set status='resolved',resolved_at=now(),resolved_by=auth.uid()
  where id=p_review_id;

  if v_review.source_type='service' then
    update public.service_catalog
    set last_contract_master_version=v_review.contract_master_version
    where code=v_review.source_code;
  elsif v_review.source_type='level' then
    update public.service_level_catalog
    set last_contract_master_version=v_review.contract_master_version
    where code=v_review.source_code;
  elsif v_review.source_type='text' then
    update public.document_text_catalog
    set last_contract_master_version=v_review.contract_master_version
    where code=v_review.source_code;
  end if;

  insert into public.audit_log(user_id,action,entity_type,entity_id,details)
  values(auth.uid(),'confirm_document_rule_review','document_rule_reviews',v_review.id,
    jsonb_build_object(
      'contract_master_version',v_review.contract_master_version,
      'source_type',v_review.source_type,
      'source_code',v_review.source_code,
      'confirmed_without_change',true
    ));
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_contract_master_current()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.contract_master_versions%rowtype;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessário'; end if;
  select * into v_row from public.contract_master_versions where active=true order by version desc limit 1;
  return coalesce(to_jsonb(v_row),'{}'::jsonb);
end
$function$

CREATE OR REPLACE FUNCTION public.admin_convert_commercial_record(p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  r public.commercial_records%rowtype;
  v_client uuid;
  v_contract uuid;
  v_project uuid;
  v_project_name text;
  v_source_project public.projetos%rowtype;
  item jsonb;
  v_code text;
  v_name text;
  v_origin_quote text;
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  select * into r
  from public.commercial_records
  where id=p_record_id
  for update;

  if not found then
    raise exception 'Registro comercial não encontrado';
  end if;

  if r.record_kind<>'contrato' then
    raise exception 'Selecione um contrato independente para formalizar cliente/projeto';
  end if;

  if r.linked_project_id is not null then
    return jsonb_build_object(
      'client_id',r.linked_client_id,
      'contract_id',r.linked_contract_id,
      'project_id',r.linked_project_id
    );
  end if;

  select q.quote_number into v_origin_quote
  from public.commercial_contract_quote_links l
  join public.commercial_records q on q.id=l.quote_record_id
  where l.contract_record_id=r.id
  order by l.created_at
  limit 1;

  if r.source_project_id is not null then
    select * into v_source_project
    from public.projetos
    where id=r.source_project_id
    for update;

    if not found then
      raise exception 'Projeto do orçamento de origem não encontrado';
    end if;

    v_origin_quote:=coalesce(v_origin_quote,v_source_project.numero_orcamento);
    v_project:=v_source_project.id;
    v_client:=v_source_project.cliente_id;
  end if;

  if v_client is null and r.email is not null then
    select id into v_client
    from public.clientes
    where lower(btrim(email))=lower(btrim(r.email))
    limit 1;
  end if;

  if v_client is null and r.cpf_cnpj is not null then
    select id into v_client
    from public.clientes
    where regexp_replace(coalesce(cpf_cnpj,''),'\D','','g')=
          regexp_replace(r.cpf_cnpj,'\D','','g')
    limit 1;
  end if;

  if v_client is null then
    insert into public.clientes(
      nome,cpf_cnpj,telefone,email,endereco,cidade,estado,cep,status,parceria
    )
    values(
      r.prospect_name,r.cpf_cnpj,r.phone,r.email,r.address,r.city,r.state,r.cep,'ativo',false
    )
    returning id into v_client;
  end if;

  if v_project is not null and v_source_project.contract_id is not null then
    v_contract:=v_source_project.contract_id;

    update public.contratos
    set
      legacy_contract_number = case
        when contract_number is distinct from r.contract_number
          then coalesce(legacy_contract_number,contract_number)
        else legacy_contract_number
      end,
      contract_number=r.contract_number,
      cliente_id=v_client,
      service_type=coalesce(r.custom_service,r.property_type,service_type),
      status='ativo',
      contract_value=coalesce(r.total_value,contract_value),
      currency='BRL',
      notes=concat_ws(
        ' | ',
        case when v_origin_quote is not null then 'Vinculado ao orçamento '||v_origin_quote end,
        nullif(r.notes,''),
        nullif(notes,'')
      ),
      updated_at=now()
    where id=v_contract;
  else
    insert into public.contratos(
      cliente_id,contract_number,service_type,status,contract_value,currency,notes
    )
    values(
      v_client,
      r.contract_number,
      coalesce(r.custom_service,r.property_type),
      'ativo',
      r.total_value,
      'BRL',
      concat_ws(
        ' | ',
        case when v_origin_quote is not null then 'Vinculado ao orçamento '||v_origin_quote end,
        r.notes
      )
    )
    returning id into v_contract;
  end if;

  if v_project is null then
    v_project_name:=coalesce(nullif(r.property_type,''),'Projeto')||' — '||r.prospect_name;

    insert into public.projetos(
      cliente_id,nome,tipo,status,numero_contrato,numero_orcamento,
      area_construida_m2,area_terreno_m2,cep_obra,endereco_obra,
      cidade_obra,estado_obra,contract_id,parceria
    )
    values(
      v_client,v_project_name,r.property_type,'ativo',r.contract_number,v_origin_quote,
      r.area_construida_m2,r.area_terreno_m2,r.cep,r.property_address,
      r.city,r.state,v_contract,false
    )
    returning id into v_project;
  else
    update public.projetos
    set
      cliente_id=v_client,
      numero_contrato=r.contract_number,
      numero_orcamento=coalesce(numero_orcamento,v_origin_quote),
      contract_id=v_contract,
      tipo=coalesce(nullif(r.property_type,''),tipo),
      area_construida_m2=coalesce(r.area_construida_m2,area_construida_m2),
      area_terreno_m2=coalesce(r.area_terreno_m2,area_terreno_m2),
      cep_obra=coalesce(nullif(r.cep,''),cep_obra),
      endereco_obra=coalesce(nullif(r.property_address,''),endereco_obra),
      cidade_obra=coalesce(nullif(r.city,''),cidade_obra),
      estado_obra=coalesce(nullif(r.state,''),estado_obra)
    where id=v_project;
  end if;

  for item in
    select * from jsonb_array_elements(coalesce(r.services,'[]'::jsonb))
  loop
    if coalesce((item->>'included')::boolean,true) then
      v_code:=nullif(btrim(item->>'code'),'');
      v_name:=nullif(btrim(item->>'name'),'');
      if v_code is not null and v_name is not null then
        insert into public.contract_scope_items(
          contract_id,service_code,service_name,included,
          acceptance_required,display_order,notes
        )
        values(
          v_contract,v_code,v_name,true,
          coalesce((item->>'acceptanceRequired')::boolean,true),
          coalesce((item->>'displayOrder')::integer,0),
          nullif(item->>'notes','')
        )
        on conflict(contract_id,service_code)
        do update set
          service_name=excluded.service_name,
          included=true,
          acceptance_required=excluded.acceptance_required,
          display_order=excluded.display_order,
          notes=excluded.notes,
          updated_at=now();
      end if;
    end if;
  end loop;

  update public.commercial_records
  set
    linked_client_id=v_client,
    linked_contract_id=v_contract,
    linked_project_id=v_project,
    status='convertido',
    updated_at=now()
  where id=r.id;

  update public.documentos
  set cliente_id=v_client,projeto_id=v_project,contract_id=v_contract
  where id=r.contract_document_id and id is not null;

  insert into public.audit_log(user_id,action,entity_type,entity_id,details)
  values(
    auth.uid(),
    'convert_independent_contract',
    'commercial_records',
    r.id,
    jsonb_build_object(
      'client_id',v_client,
      'contract_id',v_contract,
      'project_id',v_project,
      'origin_quote',v_origin_quote,
      'reused_source_project',r.source_project_id is not null
    )
  );

  return jsonb_build_object(
    'client_id',v_client,
    'contract_id',v_contract,
    'project_id',v_project
  );
end
$function$

CREATE OR REPLACE FUNCTION public.admin_create_commercial_record(p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_quote text;
  v_area_terreno numeric;
  v_area_construida numeric;
  v_total numeric;
  v_raw text;
  v_level text;
  v_services jsonb;
  v_master_id uuid;
  v_master_version integer;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessário'; end if;
  perform public.assert_document_governance_ready();

  if nullif(btrim(p_data->>'prospect_name'),'') is null then
    raise exception 'Nome do prospect é obrigatório';
  end if;

  select id,version into v_master_id,v_master_version
  from public.contract_master_versions
  where active=true
  order by version desc
  limit 1;

  v_level := lower(nullif(btrim(p_data->>'experience_level'),''));
  if v_level is not null and not exists(
    select 1 from public.service_level_catalog where code=v_level and active=true
  ) then
    raise exception 'Nível de prestação inválido ou inativo';
  end if;

  v_services := public.enrich_commercial_services(coalesce(p_data->'services','[]'::jsonb),v_level);

  v_raw := nullif(btrim(p_data->>'area_terreno_m2'),'');
  if v_raw is not null then
    v_area_terreno := case when v_raw like '%,%' then replace(replace(v_raw,'.',''),',','.')::numeric else replace(v_raw,' ','')::numeric end;
  end if;

  v_raw := nullif(btrim(p_data->>'area_construida_m2'),'');
  if v_raw is not null then
    v_area_construida := case when v_raw like '%,%' then replace(replace(v_raw,'.',''),',','.')::numeric else replace(v_raw,' ','')::numeric end;
  end if;

  v_raw := nullif(btrim(p_data->>'total_value'),'');
  if v_raw is not null then
    v_total := case when v_raw like '%,%' then replace(replace(v_raw,'.',''),',','.')::numeric else replace(v_raw,' ','')::numeric end;
  end if;

  v_quote := public.admin_next_commercial_number('ORC');

  insert into public.commercial_records(
    quote_number,prospect_name,cpf_cnpj,email,phone,cep,address,city,state,
    property_address,property_type,area_terreno_m2,area_construida_m2,construction_standard,
    experience_level,services,custom_service,total_value,payment_terms,valid_until,notes,
    contract_master_id,contract_master_version
  ) values (
    v_quote,btrim(p_data->>'prospect_name'),nullif(btrim(p_data->>'cpf_cnpj'),''),nullif(btrim(p_data->>'email'),''),
    nullif(btrim(p_data->>'phone'),''),nullif(btrim(p_data->>'cep'),''),nullif(btrim(p_data->>'address'),''),
    nullif(btrim(p_data->>'city'),''),nullif(btrim(p_data->>'state'),''),nullif(btrim(p_data->>'property_address'),''),
    nullif(btrim(p_data->>'property_type'),''),v_area_terreno,v_area_construida,
    nullif(btrim(p_data->>'construction_standard'),''),v_level,v_services,
    nullif(btrim(p_data->>'custom_service'),''),v_total,
    coalesce(p_data->'payment_terms','[]'::jsonb),
    coalesce(nullif(p_data->>'valid_until','')::date,current_date+15),
    nullif(btrim(p_data->>'notes'),''),
    v_master_id,v_master_version
  )
  returning id into v_id;

  insert into public.audit_log(user_id,action,entity_type,entity_id,details)
  values(auth.uid(),'create_commercial_record','commercial_records',v_id,
    jsonb_build_object(
      'quote_number',v_quote,
      'experience_level',v_level,
      'catalog_snapshot',true,
      'contract_master_version',v_master_version
    ));

  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_create_independent_contract(p_data jsonb, p_quote_ids uuid[] DEFAULT '{}'::uuid[], p_source_project_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_contract text;
  v_source public.commercial_records%rowtype;
  v_project public.projetos%rowtype;
  v_client public.clientes%rowtype;
  v_existing_contract public.contratos%rowtype;
  v_q uuid;
  v_raw text;
  v_total numeric;
  v_area_terreno numeric;
  v_area_construida numeric;
  v_property_address text;
  v_source_count integer := coalesce(array_length(p_quote_ids,1),0);
  v_level text;
  v_services jsonb;
  v_master_id uuid;
  v_master_version integer;
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;
  perform public.assert_document_governance_ready();

  if v_source_count > 0 and p_source_project_id is not null then
    raise exception 'Selecione apenas uma origem de orçamento';
  end if;

  if v_source_count > 0 then
    select * into v_source
    from public.commercial_records
    where id=p_quote_ids[1] and record_kind='orcamento';
    if not found then raise exception 'Orçamento de origem inválido'; end if;
  end if;

  if p_source_project_id is not null then
    select * into v_project from public.projetos where id=p_source_project_id;
    if not found or nullif(btrim(coalesce(v_project.numero_orcamento,'')),'') is null then
      raise exception 'Orçamento de origem inválido';
    end if;
    if v_project.cliente_id is not null then
      select * into v_client from public.clientes where id=v_project.cliente_id;
    end if;
    if v_project.contract_id is not null then
      select * into v_existing_contract from public.contratos where id=v_project.contract_id;
    end if;
    v_property_address := nullif(concat_ws(', ',
      nullif(btrim(v_project.endereco_obra),''),
      nullif(btrim(v_project.numero_obra),''),
      nullif(btrim(v_project.complemento_obra),''),
      nullif(btrim(v_project.bairro_obra),''),
      nullif(btrim(v_project.cidade_obra),''),
      nullif(btrim(v_project.estado_obra),'')
    ),'');
  end if;

  if nullif(btrim(coalesce(p_data->>'prospect_name',v_source.prospect_name,v_client.nome)),'') is null then
    raise exception 'Nome / razão social é obrigatório';
  end if;

  v_level := lower(coalesce(
    nullif(btrim(p_data->>'experience_level'),''),
    nullif(btrim(v_source.experience_level),'')
  ));

  if v_level is not null and not exists(
    select 1 from public.service_level_catalog where code=v_level and active=true
  ) then
    raise exception 'Nível de prestação inválido ou inativo';
  end if;

  v_services := public.enrich_commercial_services(
    coalesce(p_data->'services',v_source.services,'[]'::jsonb),
    v_level
  );

  if v_source.contract_master_id is not null then
    v_master_id := v_source.contract_master_id;
    v_master_version := v_source.contract_master_version;
  else
    select id,version into v_master_id,v_master_version
    from public.contract_master_versions
    where active=true
    order by version desc
    limit 1;
  end if;

  v_raw:=nullif(btrim(p_data->>'total_value'),'');
  if v_raw is not null then
    v_total:=case when v_raw like '%,%' then replace(replace(v_raw,'.',''),',','.')::numeric else replace(v_raw,' ','')::numeric end;
  else
    v_total:=coalesce(v_source.total_value,v_existing_contract.contract_value);
  end if;

  v_raw:=nullif(btrim(p_data->>'area_terreno_m2'),'');
  if v_raw is not null then
    v_area_terreno:=case when v_raw like '%,%' then replace(replace(v_raw,'.',''),',','.')::numeric else replace(v_raw,' ','')::numeric end;
  else
    v_area_terreno:=coalesce(v_source.area_terreno_m2,v_project.area_terreno_m2);
  end if;

  v_raw:=nullif(btrim(p_data->>'area_construida_m2'),'');
  if v_raw is not null then
    v_area_construida:=case when v_raw like '%,%' then replace(replace(v_raw,'.',''),',','.')::numeric else replace(v_raw,' ','')::numeric end;
  else
    v_area_construida:=coalesce(v_source.area_construida_m2,v_project.area_construida_m2);
  end if;

  v_contract:=public.admin_next_commercial_number('CON');

  insert into public.commercial_records(
    quote_number,contract_number,record_kind,source_mode,status,
    prospect_name,cpf_cnpj,email,phone,cep,address,city,state,
    property_address,property_type,area_terreno_m2,area_construida_m2,
    construction_standard,experience_level,services,custom_service,
    total_value,payment_terms,valid_until,notes,source_project_id,
    contract_master_id,contract_master_version
  )
  values(
    'REF-'||v_contract,v_contract,'contrato',
    case when v_source_count>0 then 'orcamento'
         when p_source_project_id is not null then 'projeto_orcamento'
         else 'manual' end,
    'rascunho_orcamento',
    coalesce(nullif(btrim(p_data->>'prospect_name'),''),v_source.prospect_name,v_client.nome),
    coalesce(nullif(btrim(p_data->>'cpf_cnpj'),''),v_source.cpf_cnpj,v_client.cpf_cnpj),
    coalesce(nullif(btrim(p_data->>'email'),''),v_source.email,v_client.email),
    coalesce(nullif(btrim(p_data->>'phone'),''),v_source.phone,v_client.telefone),
    coalesce(nullif(btrim(p_data->>'cep'),''),v_source.cep,v_project.cep_obra,v_client.cep),
    coalesce(nullif(btrim(p_data->>'address'),''),v_source.address,v_client.endereco),
    coalesce(nullif(btrim(p_data->>'city'),''),v_source.city,v_project.cidade_obra,v_client.cidade),
    coalesce(nullif(btrim(p_data->>'state'),''),v_source.state,v_project.estado_obra,v_client.estado),
    coalesce(nullif(btrim(p_data->>'property_address'),''),v_source.property_address,v_property_address),
    coalesce(nullif(btrim(p_data->>'property_type'),''),v_source.property_type,v_project.tipo,v_existing_contract.service_type),
    v_area_terreno,v_area_construida,
    coalesce(nullif(btrim(p_data->>'construction_standard'),''),v_source.construction_standard),
    v_level,v_services,
    coalesce(nullif(btrim(p_data->>'custom_service'),''),v_source.custom_service),
    v_total,
    coalesce(p_data->'payment_terms',v_source.payment_terms,'[]'::jsonb),
    current_date+30,
    coalesce(nullif(btrim(p_data->>'notes'),''),v_source.notes,v_existing_contract.notes),
    p_source_project_id,
    v_master_id,v_master_version
  )
  returning id into v_id;

  foreach v_q in array coalesce(p_quote_ids,'{}'::uuid[]) loop
    if not exists(select 1 from public.commercial_records where id=v_q and record_kind='orcamento') then
      raise exception 'Um dos vínculos não é um orçamento válido';
    end if;
    insert into public.commercial_contract_quote_links(contract_record_id,quote_record_id)
    values(v_id,v_q)
    on conflict do nothing;
  end loop;

  insert into public.audit_log(user_id,action,entity_type,entity_id,details)
  values(auth.uid(),'create_independent_contract','commercial_records',v_id,
    jsonb_build_object(
      'contract_number',v_contract,
      'quote_ids',to_jsonb(coalesce(p_quote_ids,'{}'::uuid[])),
      'source_project_id',p_source_project_id,
      'source_quote_number',v_project.numero_orcamento,
      'experience_level',v_level,
      'catalog_snapshot',true,
      'contract_master_version',v_master_version
    ));

  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_create_prospect_access_link(p_commercial_record_id uuid, p_expires_hours integer DEFAULT 72)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token text := encode(extensions.gen_random_bytes(24),'hex');
  v_link uuid;
  v_documents integer;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessário'; end if;
  if p_expires_hours not between 1 and 720 then raise exception 'Validade deve ficar entre 1 e 720 horas'; end if;
  if not exists(select 1 from public.commercial_records where id=p_commercial_record_id) then
    raise exception 'Registro comercial não encontrado';
  end if;
  insert into public.prospect_access_links(commercial_record_id,token_hash,expires_at)
  values(p_commercial_record_id,encode(extensions.digest(v_token,'sha256'),'hex'),now()+make_interval(hours=>p_expires_hours))
  returning id into v_link;
  insert into public.prospect_access_documents(link_id,document_id)
  select v_link,document_id
  from (
    select quote_document_id document_id from public.commercial_records where id=p_commercial_record_id
    union
    select contract_document_id from public.commercial_records where id=p_commercial_record_id
  ) available
  where document_id is not null;
  get diagnostics v_documents=row_count;
  if v_documents=0 then raise exception 'Gere e arquive ao menos um documento antes de criar o link'; end if;
  return v_token;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_document_governance_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_contract jsonb;
  v_master integer;
  v_pending integer;
  v_outdated_services integer;
  v_outdated_levels integer;
  v_outdated_texts integer;
  v_missing_refs integer;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessario'; end if;

  select to_jsonb(c)-'body',c.version into v_contract,v_master
  from public.contract_master_versions c
  where c.active=true order by c.version desc limit 1;

  select count(*) into v_pending
  from public.document_rule_reviews
  where contract_master_version=v_master and status='pending';

  select count(*) into v_outdated_services
  from public.service_catalog where active=true and last_contract_master_version is distinct from v_master;
  select count(*) into v_outdated_levels
  from public.service_level_catalog where active=true and last_contract_master_version is distinct from v_master;
  select count(*) into v_outdated_texts
  from public.document_text_catalog where active=true and last_contract_master_version is distinct from v_master;

  select
    (select count(*) from public.service_catalog where active=true and cardinality(contract_clause_refs)=0) +
    (select count(*) from public.service_level_catalog where active=true and cardinality(contract_clause_refs)=0) +
    (select count(*) from public.document_text_catalog where active=true and cardinality(contract_clause_refs)=0)
  into v_missing_refs;

  return jsonb_build_object(
    'contract',coalesce(v_contract,'{}'::jsonb),
    'pending_reviews',coalesce((
      select jsonb_agg(to_jsonb(r) order by r.source_type,r.source_code)
      from public.document_rule_reviews r
      where r.status='pending' and r.contract_master_version=v_master
    ),'[]'::jsonb),
    'services',coalesce((select jsonb_agg(to_jsonb(s) order by s.code) from public.service_catalog s where s.active=true),'[]'::jsonb),
    'levels',coalesce((select jsonb_agg(to_jsonb(l) order by l.code) from public.service_level_catalog l where l.active=true),'[]'::jsonb),
    'texts',coalesce((select jsonb_agg(to_jsonb(t) order by t.document_kind,t.code) from public.document_text_catalog t where t.active=true),'[]'::jsonb),
    'preflight',jsonb_build_object(
      'ready',v_master is not null and v_pending=0 and v_outdated_services=0 and
              v_outdated_levels=0 and v_outdated_texts=0 and v_missing_refs=0,
      'pending_total',v_pending,
      'pending_by_type',coalesce((
        select jsonb_object_agg(source_type,total)
        from (
          select source_type,count(*) total
          from public.document_rule_reviews
          where contract_master_version=v_master and status='pending'
          group by source_type
        ) grouped
      ),'{}'::jsonb),
      'outdated_services',v_outdated_services,
      'outdated_levels',v_outdated_levels,
      'outdated_texts',v_outdated_texts,
      'items_without_clause_refs',v_missing_refs
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.admin_next_commercial_number(p_kind text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_kind text := upper(btrim(p_kind)); v_year integer; v_month integer; v_value integer;
BEGIN
  IF NOT public.is_portal_admin() THEN RAISE EXCEPTION 'Acesso administrativo necessário'; END IF;
  IF v_kind NOT IN ('ORC','CON') THEN RAISE EXCEPTION 'Tipo de numeração inválido'; END IF;
  v_year := extract(year from timezone('America/Sao_Paulo', now()))::integer;
  v_month := extract(month from timezone('America/Sao_Paulo', now()))::integer;
  INSERT INTO public.document_number_counters(kind, year, month, last_value)
  VALUES (v_kind, v_year, v_month, 1)
  ON CONFLICT (kind, year, month) DO UPDATE SET last_value = public.document_number_counters.last_value + 1, updated_at = now()
  RETURNING last_value INTO v_value;
  RETURN format('%s-%s-%s-%s', v_kind, v_year, lpad(v_month::text,2,'0'), lpad(v_value::text,4,'0'));
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_prepare_contract_document(p_project_id uuid, p_document_kind text, p_approval_id uuid DEFAULT NULL::uuid, p_extra_data jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project record;
  v_approval public.aprovacoes%rowtype;
  v_document_id uuid;
  v_title text;
  v_optional boolean := true;
  v_data jsonb;
  v_commercial record;
  v_level jsonb := null;
  v_scope_snapshot jsonb := '[]'::jsonb;
  v_text_snapshot jsonb := '{}'::jsonb;
  v_master_id uuid;
  v_master_version integer;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessário'; end if;

  if p_document_kind not in (
    'anexo_i','termo_aceite','estudo_preliminar','levantamento_tecnico',
    'servico_adicional','autorizacao_imagem','quitacao_encerramento'
  ) then raise exception 'Tipo de documento não suportado'; end if;

  select
    p.id,p.cliente_id,p.contract_id,p.nome as project_name,p.tipo as project_type,
    p.area_construida_m2,p.area_terreno_m2,p.endereco_obra,p.numero_obra,
    p.complemento_obra,p.bairro_obra,p.cidade_obra,p.estado_obra,p.descricao as project_description,
    c.contract_number,c.signed_at,c.contract_value,c.currency,c.notes as contract_notes,
    cl.nome as client_name,cl.email as client_email,cl.telefone as client_phone,
    cl.cpf_cnpj as client_cpf_cnpj
  into v_project
  from public.projetos p
  join public.contratos c on c.id=p.contract_id
  left join public.clientes cl on cl.id=p.cliente_id
  where p.id=p_project_id;

  if not found then raise exception 'Projeto/contrato não encontrado'; end if;

  select
    cr.id,cr.experience_level,cr.services,cr.notes,cr.quote_number,cr.contract_number,
    cr.payment_terms,cr.total_value,cr.contract_master_id,cr.contract_master_version,cr.smart_texts
  into v_commercial
  from public.commercial_records cr
  where cr.linked_contract_id=v_project.contract_id or cr.linked_project_id=p_project_id
  order by (cr.record_kind='contrato') desc,cr.updated_at desc
  limit 1;

  if v_commercial.contract_master_id is not null then
    v_master_id := v_commercial.contract_master_id;
    v_master_version := v_commercial.contract_master_version;
  else
    select id,version into v_master_id,v_master_version
    from public.contract_master_versions where active=true order by version desc limit 1;
  end if;

  v_text_snapshot := case
    when v_commercial.smart_texts is not null and v_commercial.smart_texts <> '{}'::jsonb
      then v_commercial.smart_texts
    else public.current_document_text_snapshot_all()
  end;

  select item->'level'
  into v_level
  from jsonb_array_elements(coalesce(v_commercial.services,'[]'::jsonb)) item
  where jsonb_typeof(item->'level')='object'
  limit 1;

  if v_level is null
     and nullif(btrim(coalesce(v_commercial.experience_level,'')),'') is not null then
    select jsonb_build_object(
      'code',l.code,'label',l.label,'subtitle',l.subtitle,'description',l.description,
      'features',l.features,'exclusions',l.exclusions,
      'contractClauses',to_jsonb(l.contract_clause_refs),'catalogVersion',l.version
    ) into v_level
    from public.service_level_catalog l
    where l.code=lower(v_commercial.experience_level) and l.active=true;
  end if;

  select coalesce(jsonb_agg(
    (
      coalesce(
        (
          select item
          from jsonb_array_elements(coalesce(v_commercial.services,'[]'::jsonb)) item
          where item->>'code'=s.service_code limit 1
        ),
        jsonb_build_object(
          'code',s.service_code,'name',coalesce(sc.name,s.service_name),
          'description',sc.description,'deliverables',coalesce(sc.deliverables,'[]'::jsonb),
          'exclusions',coalesce(sc.exclusions,'[]'::jsonb),
          'clientInputs',coalesce(sc.client_inputs,'[]'::jsonb),
          'revisions',sc.default_revisions,
          'deliveryFormats',coalesce(sc.delivery_formats,'["PDF"]'::jsonb),
          'planningReference',sc.planning_reference,
          'contractClauses',to_jsonb(coalesce(sc.contract_clause_refs,'{}'::text[])),
          'catalogVersion',sc.version,'levelApplicable',coalesce(sc.level_applicable,false),
          'level',case when coalesce(sc.level_applicable,false) and v_level is not null then v_level else null end
        )
      )
      || jsonb_build_object(
        'included',s.included,'acceptanceRequired',s.acceptance_required,
        'displayOrder',s.display_order,'notes',s.notes
      )
    ) order by s.display_order
  ),'[]'::jsonb)
  into v_scope_snapshot
  from public.contract_scope_items s
  left join public.service_catalog sc on sc.code=s.service_code
  where s.contract_id=v_project.contract_id;

  if p_document_kind='termo_aceite' then
    if p_approval_id is null then raise exception 'Selecione uma aprovação para gerar o Termo de Aceite'; end if;
    select * into v_approval from public.aprovacoes
    where id=p_approval_id and projeto_id=p_project_id;
    if not found then raise exception 'Aprovação não encontrada para este projeto'; end if;
  end if;

  v_title := case p_document_kind
    when 'anexo_i' then 'Anexo I — Escopo de Serviços, Proposta Comercial e Cronograma'
    when 'termo_aceite' then 'Termo de Aceite de Etapa — ' || coalesce(v_approval.titulo,'Etapa')
    when 'estudo_preliminar' then 'Estudo Preliminar'
    when 'levantamento_tecnico' then 'Ficha de Levantamento Técnico / Vistoria'
    when 'servico_adicional' then 'Termo de Aprovação de Orçamento — Serviço Adicional'
    when 'autorizacao_imagem' then 'Autorização de Uso de Imagem e Divulgação do Projeto'
    when 'quitacao_encerramento' then 'Termo de Quitação e Encerramento de Contrato'
  end;

  v_optional := p_document_kind not in ('anexo_i','termo_aceite');

  v_data := jsonb_build_object(
    'contract_number',v_project.contract_number,'contract_signed_at',v_project.signed_at,
    'contract_value',v_project.contract_value,'currency',v_project.currency,
    'contract_notes',v_project.contract_notes,'client_name',v_project.client_name,
    'client_email',v_project.client_email,'client_phone',v_project.client_phone,
    'client_cpf_cnpj',v_project.client_cpf_cnpj,'project_name',v_project.project_name,
    'project_type',v_project.project_type,'project_description',v_project.project_description,
    'area_construida_m2',v_project.area_construida_m2,'area_terreno_m2',v_project.area_terreno_m2,
    'property_address',concat_ws(', ',
      nullif(v_project.endereco_obra,''),nullif(v_project.numero_obra,''),
      nullif(v_project.complemento_obra,''),nullif(v_project.bairro_obra,''),
      nullif(v_project.cidade_obra,''),nullif(v_project.estado_obra,'')
    ),
    'experience_level',v_commercial.experience_level,'service_level',v_level,
    'scope_snapshot',v_scope_snapshot,'smart_texts',v_text_snapshot,
    'contract_master_id',v_master_id,'contract_master_version',v_master_version,
    'source_quote_number',v_commercial.quote_number,'commercial_notes',v_commercial.notes,
    'payment_terms',v_commercial.payment_terms,
    'outside_contracted_scope',case
      when p_document_kind='estudo_preliminar' then not exists(
        select 1 from public.contract_scope_items s
        where s.contract_id=v_project.contract_id and s.service_code='a' and s.included=true
      )
      else false
    end
  ) || coalesce(p_extra_data,'{}'::jsonb);

  if p_document_kind='termo_aceite' then
    v_data := v_data || jsonb_build_object(
      'approval_id',v_approval.id,'approval_type',v_approval.tipo,'approval_title',v_approval.titulo,
      'approval_description',v_approval.descricao,'delivered_at',v_approval.delivered_at,
      'approval_due_at',v_approval.approval_due_at,'approval_status',v_approval.status
    );
  end if;

  if p_document_kind='anexo_i' then
    v_data := v_data || jsonb_build_object('scope_items',v_scope_snapshot);
  end if;

  insert into public.documentos(
    cliente_id,projeto_id,contract_id,approval_id,nome,tipo,categoria,versao,
    storage_bucket,permitir_download,protection_mode,document_kind,workflow_status,
    generated_data,optional_document
  ) values (
    v_project.cliente_id,v_project.id,v_project.contract_id,p_approval_id,v_title,
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'Contratual','1.0','documentos',true,'administrative',p_document_kind,'rascunho',
    v_data,v_optional
  ) returning id into v_document_id;

  insert into public.audit_log(user_id,action,entity_type,entity_id,details)
  values(auth.uid(),'prepare_contract_document','documentos',v_document_id,
    jsonb_build_object(
      'document_kind',p_document_kind,'project_id',p_project_id,'catalog_snapshot',true,
      'experience_level',v_commercial.experience_level,'contract_master_version',v_master_version,
      'smart_text_snapshot',true
    ));

  return v_document_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_preview_contract_document(p_project_id uuid, p_document_kind text, p_approval_id uuid DEFAULT NULL::uuid, p_extra_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v record; v_prev record; v_scope jsonb; v_major int:=1; v_minor int:=0; v_bump text:=lower(coalesce(p_extra_data->>'version_bump','minor')); v_next text;
begin
 if not public.is_portal_admin() then raise exception 'Acesso administrativo necessário'; end if;
 select p.id,p.nome project_name,p.tipo project_type,p.endereco_obra,p.numero_obra,p.complemento_obra,p.bairro_obra,p.cidade_obra,p.estado_obra,p.contract_id,p.cliente_id,c.contract_number,c.contract_value,cl.nome client_name,cl.cpf_cnpj client_cpf_cnpj,cl.endereco client_address into v from public.projetos p join public.contratos c on c.id=p.contract_id left join public.clientes cl on cl.id=p.cliente_id where p.id=p_project_id;
 if not found then raise exception 'Projeto/contrato não encontrado'; end if;
 select d.id,d.versao into v_prev from public.documentos d where d.projeto_id=p_project_id and d.document_kind=p_document_kind and (p_approval_id is null or d.approval_id is not distinct from p_approval_id) order by d.created_at desc limit 1;
 if found then begin v_major:=split_part(coalesce(v_prev.versao,'1.0'),'.',1)::int; exception when others then v_major:=1; end; begin v_minor:=split_part(coalesce(v_prev.versao,'1.0'),'.',2)::int; exception when others then v_minor:=0; end; if v_bump='major' then v_major:=v_major+1;v_minor:=0;else v_minor:=v_minor+1;end if; end if;
 v_next:=v_major::text||'.'||v_minor::text;
 select coalesce(jsonb_agg(jsonb_build_object('code',s.service_code,'name',s.service_name,'included',s.included) order by s.display_order),'[]'::jsonb) into v_scope from public.contract_scope_items s where s.contract_id=v.contract_id and s.included=true;
 return jsonb_build_object('document_kind',p_document_kind,'next_version',v_next,'revision_of',v_prev.id,'client_name',v.client_name,'client_cpf_cnpj',v.client_cpf_cnpj,'client_address',v.client_address,'project_name',v.project_name,'project_type',v.project_type,'contract_number',v.contract_number,'contract_value',v.contract_value,'property_address',concat_ws(', ',nullif(v.endereco_obra,''),nullif(v.numero_obra,''),nullif(v.complemento_obra,''),nullif(v.bairro_obra,''),nullif(v.cidade_obra,''),nullif(v.estado_obra,'')),'scope_items',v_scope,'document_options',coalesce(p_extra_data->'document_options','{}'::jsonb));
end; $function$

CREATE OR REPLACE FUNCTION public.admin_professional_identity_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare
  v_data jsonb := '{}'::jsonb;
  v_secret text;
  v_cpf text;
  v_rg text;
  v_cnpj text;
  v_has_crea boolean;
  v_document_ready boolean;
  v_contract_ready boolean;
  v_missing jsonb := '[]'::jsonb;
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name='cme_professional_identity'
  limit 1;

  if nullif(v_secret,'') is not null then
    v_data := v_secret::jsonb;
  end if;

  v_cpf := regexp_replace(coalesce(v_data->>'cpf',''),'\D','','g');
  v_rg := regexp_replace(coalesce(v_data->>'rg',''),'\D','','g');
  v_cnpj := regexp_replace(coalesce(v_data->>'cnpj',''),'\D','','g');

  v_has_crea :=
    nullif(btrim(coalesce(v_data->>'crea_rj','')),'') is not null
    or nullif(btrim(coalesce(v_data->>'crea_sp','')),'') is not null;

  v_document_ready :=
    nullif(btrim(coalesce(v_data->>'full_name','')),'') is not null
    and v_has_crea;

  if nullif(btrim(coalesce(v_data->>'full_name','')),'') is null then
    v_missing := v_missing || '"nome civil completo"'::jsonb;
  end if;
  if not v_has_crea then
    v_missing := v_missing || '"CREA"'::jsonb;
  end if;
  if length(v_cpf) <> 11 then
    v_missing := v_missing || '"CPF"'::jsonb;
  end if;
  if nullif(btrim(coalesce(v_data->>'professional_address','')),'') is null then
    v_missing := v_missing || '"endereço profissional"'::jsonb;
  end if;
  if nullif(btrim(coalesce(v_data->>'email_professional','')),'') is null then
    v_missing := v_missing || '"e-mail profissional"'::jsonb;
  end if;

  v_contract_ready := jsonb_array_length(v_missing) = 0;

  return jsonb_build_object(
    'configured', v_data <> '{}'::jsonb,
    'document_ready', v_document_ready,
    'contract_ready', v_contract_ready,
    'missing_contract_fields', v_missing,
    'full_name', coalesce(v_data->>'full_name',''),
    'professional_title', coalesce(v_data->>'professional_title','Engenheira Civil'),
    'nationality', coalesce(v_data->>'nationality',''),
    'marital_status', coalesce(v_data->>'marital_status',''),
    'crea_rj', coalesce(v_data->>'crea_rj',''),
    'crea_sp', coalesce(v_data->>'crea_sp',''),
    'rg_issuer', coalesce(v_data->>'rg_issuer',''),
    'professional_address', coalesce(v_data->>'professional_address',''),
    'professional_city', coalesce(v_data->>'professional_city',''),
    'professional_state', coalesce(v_data->>'professional_state',''),
    'email_professional', coalesce(v_data->>'email_professional',''),
    'phone_professional', coalesce(v_data->>'phone_professional',''),
    'cpf_set', length(v_cpf) > 0,
    'cpf_masked', case when length(v_cpf) = 11 then '•••.•••.•••-' || right(v_cpf,2) else '' end,
    'rg_set', length(v_rg) > 0,
    'rg_masked', case when length(v_rg) >= 3 then '•••••••' || right(v_rg,2) else '' end,
    'cnpj_set', length(v_cnpj) > 0,
    'cnpj_masked', case when length(v_cnpj) = 14 then '••.•••.•••/••••-' || right(v_cnpj,2) else '' end
  );
end
$function$

CREATE OR REPLACE FUNCTION public.admin_publish_contract_master(p_body text, p_label text, p_notes text DEFAULT NULL::text, p_changed_clause_refs text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_version integer;
  v_old public.contract_master_versions%rowtype;
  v_manual_refs text[];
  v_detected_refs text[];
  v_effective_refs text[];
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessario'; end if;
  if nullif(btrim(p_body),'') is null then raise exception 'O texto do Contrato Mestre e obrigatorio'; end if;
  if nullif(btrim(p_label),'') is null then raise exception 'Informe um nome para a nova versao'; end if;

  select * into v_old
  from public.contract_master_versions where active=true order by version desc limit 1;

  if v_old.id is not null and
     regexp_replace(v_old.body,'[[:space:]]+',' ','g') = regexp_replace(p_body,'[[:space:]]+',' ','g') then
    raise exception 'O texto informado e igual ao Contrato Mestre ativo. Nenhuma nova versao foi criada';
  end if;

  select coalesce(array_agg(distinct btrim(ref) order by btrim(ref)),'{}'::text[])
  into v_manual_refs
  from unnest(coalesce(p_changed_clause_refs,'{}'::text[])) ref
  where nullif(btrim(ref),'') is not null;

  v_detected_refs := case
    when v_old.id is null then '{}'::text[]
    else public.document_changed_clause_refs(v_old.body,p_body)
  end;

  select coalesce(array_agg(distinct ref order by ref),'{}'::text[])
  into v_effective_refs
  from unnest(coalesce(v_manual_refs,'{}'::text[]) || coalesce(v_detected_refs,'{}'::text[])) ref;

  select coalesce(max(version),0)+1 into v_version from public.contract_master_versions;
  update public.contract_master_versions set active=false where active=true;

  insert into public.contract_master_versions(version,label,body,notes,active,created_by)
  values(v_version,btrim(p_label),p_body,nullif(btrim(p_notes),''),true,auth.uid())
  returning id into v_id;

  insert into public.document_rule_reviews(contract_master_version,source_type,source_code,clause_refs,reason)
  select v_version,'service',s.code,s.contract_clause_refs,
    case when cardinality(v_effective_refs)=0
      then 'Nova versao do contrato publicada; revisar coerencia geral do servico.'
      else 'Clausula contratual relacionada ao servico foi alterada automaticamente.' end
  from public.service_catalog s
  where s.active=true and (cardinality(v_effective_refs)=0 or s.contract_clause_refs && v_effective_refs)
  on conflict(contract_master_version,source_type,source_code) do nothing;

  insert into public.document_rule_reviews(contract_master_version,source_type,source_code,clause_refs,reason)
  select v_version,'level',l.code,l.contract_clause_refs,
    case when cardinality(v_effective_refs)=0
      then 'Nova versao do contrato publicada; revisar coerencia geral do nivel.'
      else 'Clausula contratual relacionada ao nivel foi alterada automaticamente.' end
  from public.service_level_catalog l
  where l.active=true and (cardinality(v_effective_refs)=0 or l.contract_clause_refs && v_effective_refs)
  on conflict(contract_master_version,source_type,source_code) do nothing;

  insert into public.document_rule_reviews(contract_master_version,source_type,source_code,clause_refs,reason)
  select v_version,'text',t.code,t.contract_clause_refs,
    case when cardinality(v_effective_refs)=0
      then 'Nova versao do contrato publicada; revisar coerencia geral do texto.'
      else 'Clausula contratual relacionada ao texto foi alterada automaticamente.' end
  from public.document_text_catalog t
  where t.active=true and (cardinality(v_effective_refs)=0 or t.contract_clause_refs && v_effective_refs)
  on conflict(contract_master_version,source_type,source_code) do nothing;

  -- Itens sem interseção com as cláusulas efetivamente alteradas são
  -- promovidos automaticamente: não exigem um clique de revisão sem motivo.
  if cardinality(v_effective_refs)>0 then
    update public.service_catalog
    set last_contract_master_version=v_version
    where active=true and not (contract_clause_refs && v_effective_refs);

    update public.service_level_catalog
    set last_contract_master_version=v_version
    where active=true and not (contract_clause_refs && v_effective_refs);

    update public.document_text_catalog
    set last_contract_master_version=v_version
    where active=true and not (contract_clause_refs && v_effective_refs);
  end if;

  insert into public.audit_log(user_id,action,entity_type,entity_id,details)
  values(auth.uid(),'publish_contract_master','contract_master_versions',v_id,
    jsonb_build_object(
      'version',v_version,
      'label',p_label,
      'manual_clause_refs',to_jsonb(v_manual_refs),
      'detected_clause_refs',to_jsonb(v_detected_refs),
      'effective_clause_refs',to_jsonb(v_effective_refs),
      'general_review',cardinality(v_effective_refs)=0
    ));

  return v_id;
end
$function$

CREATE OR REPLACE FUNCTION public.admin_reset_financial_data(p_confirmation text, p_reason text DEFAULT 'accounting_reset'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_before integer := 0;
  v_archived integer := 0;
  v_deleted integer := 0;
  v_reason text;
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  if upper(btrim(coalesce(p_confirmation, ''))) <> 'RESETAR FINANCEIRO' then
    raise exception 'Confirmação inválida. Digite RESETAR FINANCEIRO.';
  end if;

  v_reason := coalesce(nullif(btrim(p_reason), ''), 'accounting_reset');

  select count(*)::integer into v_before from public.financeiro;

  v_archived := private.archive_financial_rows(
    null,
    null,
    null,
    v_reason,
    auth.uid()
  );

  perform set_config('app.financial_archive_reason', v_reason, true);
  delete from public.financeiro;
  get diagnostics v_deleted = row_count;

  return jsonb_build_object(
    'activeBefore', v_before,
    'archivedNow', v_archived,
    'deletedActive', v_deleted,
    'historyPreserved', true,
    'resetAt', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_save_professional_identity(p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare
  v_id uuid;
  v_secret text;
  v_data jsonb := '{}'::jsonb;
  v_key text;
  v_value text;
  v_cpf text;
  v_cnpj text;
  v_allowed constant text[] := array[
    'full_name',
    'professional_title',
    'nationality',
    'marital_status',
    'cpf',
    'cnpj',
    'rg',
    'rg_issuer',
    'crea_rj',
    'crea_sp',
    'professional_address',
    'professional_city',
    'professional_state',
    'email_professional',
    'phone_professional'
  ];
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  select id,decrypted_secret into v_id,v_secret
  from vault.decrypted_secrets
  where name='cme_professional_identity'
  limit 1;

  if nullif(v_secret,'') is not null then
    v_data := v_secret::jsonb;
  end if;

  foreach v_key in array v_allowed loop
    if p_patch ? v_key then
      v_value := nullif(btrim(p_patch->>v_key),'');
      if v_value is not null then
        v_data := jsonb_set(v_data,array[v_key],to_jsonb(v_value),true);
      end if;
    end if;
  end loop;

  v_cpf := regexp_replace(coalesce(v_data->>'cpf',''),'\D','','g');
  if length(v_cpf) > 0 and length(v_cpf) <> 11 then
    raise exception 'CPF deve conter 11 dígitos';
  end if;

  v_cnpj := regexp_replace(coalesce(v_data->>'cnpj',''),'\D','','g');
  if length(v_cnpj) > 0 and length(v_cnpj) <> 14 then
    raise exception 'CNPJ deve conter 14 dígitos';
  end if;

  if nullif(btrim(v_data->>'crea_rj'),'') is null
     and nullif(btrim(v_data->>'crea_sp'),'') is null then
    raise exception 'Informe ao menos uma inscrição no CREA';
  end if;

  if v_id is null then
    perform vault.create_secret(
      v_data::text,
      'cme_professional_identity',
      'Identidade civil e profissional usada exclusivamente na geração segura de documentos'
    );
  else
    perform vault.update_secret(
      v_id,
      v_data::text,
      'cme_professional_identity',
      'Identidade civil e profissional usada exclusivamente na geração segura de documentos'
    );
  end if;

  insert into public.audit_log(user_id,action,entity_type,details)
  values(
    auth.uid(),
    'update_professional_identity',
    'secure_professional_identity',
    jsonb_build_object(
      'updated_fields',
      (
        select coalesce(jsonb_agg(key),'[]'::jsonb)
        from jsonb_object_keys(p_patch) key
      )
    )
  );

  return public.admin_professional_identity_status();
end
$function$

CREATE OR REPLACE FUNCTION public.admin_system_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_result jsonb;
begin
  select exists(select 1 from public.profiles p where p.id=v_uid and p.role='admin') into v_is_admin;
  if not v_is_admin then raise exception 'Acesso negado'; end if;
  select jsonb_build_object(
    'database','ok',
    'checked_at',now(),
    'documents_total',(select count(*) from public.documentos),
    'snapshots_total',(select count(*) from public.document_emission_snapshots),
    'legacy_snapshots',(select count(*) from public.document_emission_snapshots where legacy_backfill),
    'sha256_snapshots',(select count(*) from public.document_emission_snapshots where hash_algorithm='sha256' and length(snapshot_hash)=64),
    'pending_acceptances',(select count(*) from public.documentos where workflow_status='enviado'),
    'latest_document_generated_at',(select max(generated_at) from public.documentos),
    'latest_snapshot_at',(select max(emitted_at) from public.document_emission_snapshots)
  ) into v_result;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_upsert_document_text(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := lower(nullif(btrim(p_data->>'code'),''));
  v_old public.document_text_catalog%rowtype;
  v_version integer;
  v_master integer;
  v_row public.document_text_catalog%rowtype;
begin
  if not public.is_portal_admin() then raise exception 'Acesso administrativo necessário'; end if;
  if v_code is null or v_code !~ '^[a-z0-9_-]+$' then raise exception 'Código do texto inválido'; end if;
  if nullif(btrim(p_data->>'body'),'') is null then raise exception 'Texto padrão é obrigatório'; end if;

  select version into v_master from public.contract_master_versions where active=true order by version desc limit 1;
  select * into v_old from public.document_text_catalog where code=v_code;
  v_version := case when found then v_old.version+1 else 1 end;

  if v_old.code is not null then
    insert into public.document_text_catalog_versions(text_code,version,snapshot,contract_master_version,created_by)
    values(v_old.code,v_old.version,to_jsonb(v_old),v_old.last_contract_master_version,auth.uid())
    on conflict(text_code,version) do nothing;
  end if;

  insert into public.document_text_catalog(
    code,document_kind,title,body,contract_clause_refs,version,active,last_contract_master_version,updated_at
  ) values (
    v_code,coalesce(nullif(btrim(p_data->>'document_kind'),''),'geral'),
    coalesce(nullif(btrim(p_data->>'title'),''),v_code),btrim(p_data->>'body'),
    coalesce(array(select jsonb_array_elements_text(coalesce(p_data->'contract_clause_refs','[]'::jsonb))),'{}'::text[]),
    v_version,true,v_master,now()
  )
  on conflict(code) do update set
    document_kind=excluded.document_kind,title=excluded.title,body=excluded.body,
    contract_clause_refs=excluded.contract_clause_refs,version=excluded.version,
    active=true,last_contract_master_version=v_master,updated_at=now()
  returning * into v_row;

  insert into public.document_text_catalog_versions(text_code,version,snapshot,contract_master_version,created_by)
  values(v_row.code,v_row.version,to_jsonb(v_row),v_master,auth.uid())
  on conflict(text_code,version) do nothing;

  update public.document_rule_reviews
  set status='resolved',resolved_at=now(),resolved_by=auth.uid()
  where status='pending' and source_type='text' and source_code=v_code and contract_master_version=v_master;

  return to_jsonb(v_row);
end
$function$

