CREATE OR REPLACE FUNCTION public.assert_document_governance_ready()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_master integer;
  v_pending integer;
  v_outdated integer;
  v_missing_refs integer;
  v_missing_texts integer;
begin
  if auth.role() <> 'service_role' and not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  select version into v_master
  from public.contract_master_versions where active=true order by version desc limit 1;
  if v_master is null then
    raise exception 'Nenhum Contrato Mestre ativo foi encontrado';
  end if;

  select count(*) into v_pending
  from public.document_rule_reviews
  where contract_master_version=v_master and status='pending';

  select
    (select count(*) from public.service_catalog where active=true and last_contract_master_version is distinct from v_master) +
    (select count(*) from public.service_level_catalog where active=true and last_contract_master_version is distinct from v_master) +
    (select count(*) from public.document_text_catalog where active=true and last_contract_master_version is distinct from v_master)
  into v_outdated;

  select
    (select count(*) from public.service_catalog where active=true and cardinality(contract_clause_refs)=0) +
    (select count(*) from public.service_level_catalog where active=true and cardinality(contract_clause_refs)=0) +
    (select count(*) from public.document_text_catalog where active=true and cardinality(contract_clause_refs)=0)
  into v_missing_refs;

  select count(*) into v_missing_texts
  from unnest(array[
    'proposal_scope_governance','proposal_revision_rule','proposal_timeline_rule',
    'proposal_client_inputs_rule','anexo_scope_governance','anexo_revision_rule',
    'anexo_timeline_rule','acceptance_rule','additional_service_rule','notification_rule',
    'study_prelim_limit','survey_limit','image_authorization_conditions',
    'closing_release_rule','level_scope_rule','scope_limits_rule'
  ]) required(code)
  where not exists(
    select 1 from public.document_text_catalog t where t.code=required.code and t.active=true
  );

  if v_pending>0 or v_outdated>0 or v_missing_refs>0 or v_missing_texts>0 then
    raise exception
      'Governanca documental incompleta para o Contrato Mestre v%: % revisao(oes) pendente(s), % item(ns) desatualizado(s), % item(ns) sem clausula vinculada e % texto(s) obrigatorio(s) ausente(s). Revise em Configuracoes antes de criar ou gerar documentos.',
      v_master,v_pending,v_outdated,v_missing_refs,v_missing_texts;
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.assign_document_revision_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_prev public.documentos%rowtype; v_major int:=1; v_minor int:=0; v_bump text; v_commercial_record text;
begin
 if new.document_kind is null then return new; end if;
 v_bump:=lower(coalesce(new.generated_data->>'version_bump','minor'));
 v_commercial_record:=new.generated_data->>'commercial_record_id';
 if new.projeto_id is not null then
   select * into v_prev from public.documentos d where d.projeto_id=new.projeto_id and d.document_kind=new.document_kind and d.id<>new.id and (new.approval_id is null or d.approval_id is not distinct from new.approval_id) order by d.created_at desc limit 1;
 elsif v_commercial_record is not null then
   select * into v_prev from public.documentos d where d.document_kind=new.document_kind and d.id<>new.id and d.generated_data->>'commercial_record_id'=v_commercial_record order by d.created_at desc limit 1;
 end if;
 if found then
   begin v_major:=split_part(coalesce(v_prev.versao,'1.0'),'.',1)::int; exception when others then v_major:=1; end;
   begin v_minor:=split_part(coalesce(v_prev.versao,'1.0'),'.',2)::int; exception when others then v_minor:=0; end;
   if v_bump='major' then v_major:=v_major+1; v_minor:=0; else v_minor:=v_minor+1; end if;
   new.revision_of:=v_prev.id;
 else v_major:=1; v_minor:=0; new.revision_of:=null; end if;
 new.versao:=v_major::text||'.'||v_minor::text;
 new.version_reason:=nullif(btrim(coalesce(new.generated_data->>'version_reason','')),'');
 new.generated_data:=coalesce(new.generated_data,'{}'::jsonb)||jsonb_build_object('document_version',new.versao,'revision_of',new.revision_of,'version_reason',new.version_reason);
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.consume_admin_rate_limit(p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_limit integer;
  v_seconds integer;
  v_window timestamptz;
  v_attempts integer;
begin
  if not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  case p_action
    when 'admin-invite-client' then v_limit := 10; v_seconds := 600;
    when 'admin-delete-client' then v_limit := 3; v_seconds := 3600;
    when 'admin-delete-client-preview' then v_limit := 20; v_seconds := 600;
    when 'admin-delete-client-delete' then v_limit := 3; v_seconds := 3600;

    when 'contract-document-generate' then v_limit := 60; v_seconds := 600;
    when 'contract-document-send' then v_limit := 30; v_seconds := 600;
    when 'commercial-document-orcamento' then v_limit := 60; v_seconds := 600;
    when 'commercial-document-contrato' then v_limit := 60; v_seconds := 600;
    when 'document-delivery-download' then v_limit := 90; v_seconds := 600;
    when 'document-delivery-archive' then v_limit := 60; v_seconds := 600;
    when 'commercial-lookup-cep' then v_limit := 60; v_seconds := 600;
    when 'commercial-lookup-cnpj' then v_limit := 30; v_seconds := 600;
    when 'document-archive-preview' then v_limit := 60; v_seconds := 600;
    when 'document-archive-retain' then v_limit := 60; v_seconds := 600;
    when 'document-archive-export' then v_limit := 10; v_seconds := 3600;
    when 'document-archive-purge' then v_limit := 5; v_seconds := 3600;
    when 'document-archive-restore' then v_limit := 10; v_seconds := 3600;
    else
      raise exception 'Ação de limite inválida';
  end case;

  v_window := to_timestamp(floor(extract(epoch from now()) / v_seconds) * v_seconds);

  insert into public.app_admin_rate_limits(actor_id, action, window_start, attempts)
  values ((select auth.uid()), p_action, v_window, 1)
  on conflict (actor_id, action, window_start)
  do update set attempts = public.app_admin_rate_limits.attempts + 1
  returning attempts into v_attempts;

  if v_attempts > v_limit then
    raise exception 'Limite temporário excedido';
  end if;

  delete from public.app_admin_rate_limits
  where window_start < now() - interval '2 days';

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.document_changed_clause_refs(p_old_body text, p_new_body text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_old jsonb := public.document_contract_clause_map(p_old_body);
  v_new jsonb := public.document_contract_clause_map(p_new_body);
  v_refs text[];
begin
  if regexp_replace(coalesce(p_old_body,''),'[[:space:]]+',' ','g') =
     regexp_replace(coalesce(p_new_body,''),'[[:space:]]+',' ','g') then
    return '{}'::text[];
  end if;

  select coalesce(array_agg(key order by key),'{}'::text[])
  into v_refs
  from (
    select key
    from jsonb_object_keys(v_old || v_new) key
    where v_old->>key is distinct from v_new->>key
  ) changed;

  return v_refs;
end
$function$

CREATE OR REPLACE FUNCTION public.enrich_commercial_services(p_services jsonb, p_level text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb := '[]'::jsonb;
  v_item jsonb;
  v_catalog public.service_catalog%rowtype;
  v_level public.service_level_catalog%rowtype;
  v_code text;
  v_level_code text := lower(nullif(btrim(coalesce(p_level,'')),''));
  v_level_json jsonb;
begin
  if auth.role() <> 'service_role' and not public.is_portal_admin() then
    raise exception 'Acesso administrativo necessário';
  end if;

  if v_level_code is not null then
    select * into v_level
    from public.service_level_catalog
    where code=v_level_code and active=true;
  end if;

  for v_item in select * from jsonb_array_elements(coalesce(p_services,'[]'::jsonb))
  loop
    v_code := nullif(btrim(v_item->>'code'),'');
    if v_code is null then continue; end if;

    select * into v_catalog
    from public.service_catalog
    where code=v_code and active=true;

    if found then
      v_level_json := null;

      if v_catalog.level_applicable and v_level.code is not null then
        v_level_json := jsonb_build_object(
          'code',v_level.code,
          'label',v_level.label,
          'subtitle',v_level.subtitle,
          'description',v_level.description,
          'features',v_level.features,
          'exclusions',v_level.exclusions,
          'contractClauses',to_jsonb(v_level.contract_clause_refs),
          'catalogVersion',v_level.version
        );
      end if;

      v_result := v_result || jsonb_build_array(
        jsonb_build_object(
          'code',v_catalog.code,
          'name',v_catalog.name,
          'included',coalesce((v_item->>'included')::boolean,false),
          'value',v_item->'value',
          'notes',nullif(btrim(v_item->>'notes'),''),
          'acceptanceRequired',v_catalog.acceptance_required,
          'displayOrder',coalesce((v_item->>'displayOrder')::integer,ascii(left(v_catalog.code,1))-96),
          'description',v_catalog.description,
          'deliverables',v_catalog.deliverables,
          'exclusions',v_catalog.exclusions,
          'clientInputs',v_catalog.client_inputs,
          'revisions',v_catalog.default_revisions,
          'deliveryFormats',v_catalog.delivery_formats,
          'planningReference',v_catalog.planning_reference,
          'contractClauses',to_jsonb(v_catalog.contract_clause_refs),
          'catalogVersion',v_catalog.version,
          'levelApplicable',v_catalog.level_applicable,
          'level',v_level_json
        )
      );
    else
      v_result := v_result || jsonb_build_array(v_item);
    end if;
  end loop;

  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.freeze_commercial_document_governance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_master_id uuid;
  v_master_version integer;
begin
  if new.contract_master_id is null or new.contract_master_version is null then
    select id,version into v_master_id,v_master_version
    from public.contract_master_versions
    where active=true
    order by version desc
    limit 1;

    new.contract_master_id := coalesce(new.contract_master_id,v_master_id);
    new.contract_master_version := coalesce(new.contract_master_version,v_master_version);
  end if;

  if new.smart_texts is null or new.smart_texts='{}'::jsonb then
    if coalesce(new.record_kind,'orcamento')='contrato' then
      new.smart_texts := public.current_document_text_snapshot_all();
    else
      new.smart_texts := public.current_document_text_snapshot('orcamento');
    end if;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.google_calendar_secret_set(p_name text, p_value text, p_description text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare
  v_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'not authorized';
  end if;

  if coalesce(trim(p_name), '') = '' or coalesce(p_value, '') = '' then
    raise exception 'invalid secret';
  end if;

  select id
    into v_id
  from vault.secrets
  where name = p_name
  order by created_at desc
  limit 1;

  if v_id is null then
    perform vault.create_secret(p_value, p_name, p_description, null);
  else
    perform vault.update_secret(v_id, p_value, p_name, p_description, null);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_governance_after_service_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_master integer;
begin
  select version into v_master
  from public.contract_master_versions where active=true order by version desc limit 1;
  if v_master is null then return new; end if;

  insert into public.document_rule_reviews(
    contract_master_version,source_type,source_code,clause_refs,reason,status,
    created_at,resolved_at,resolved_by
  ) values (
    v_master,'contract','service:'||new.code,new.contract_clause_refs,
    'O servico foi incluido ou alterado. Confirme se o Contrato Mestre continua cobrindo corretamente esse escopo.',
    'pending',now(),null,null
  )
  on conflict(contract_master_version,source_type,source_code) do update set
    clause_refs=excluded.clause_refs,reason=excluded.reason,status='pending',
    created_at=now(),resolved_at=null,resolved_by=null;

  perform public.enqueue_document_text_reviews(
    v_master,
    'O catalogo de servicos mudou. Revise este texto para confirmar que escopo, limites, prazo e entregaveis continuam coerentes.',
    null
  );
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.registrar_push_diagnostico(p_cliente_id uuid, p_etapa text, p_codigo text DEFAULT NULL::text, p_mensagem text DEFAULT NULL::text, p_permissao text DEFAULT NULL::text, p_navegador text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return;
  end if;

  if not exists (
    select 1 from public.clientes c
    where c.id = p_cliente_id
      and c.auth_id = v_uid
  ) then
    return;
  end if;

  insert into public.push_diagnosticos(
    cliente_id, auth_user_id, etapa, codigo, mensagem, permissao, navegador
  )
  values(
    p_cliente_id,
    v_uid,
    left(coalesce(p_etapa,'desconhecida'),80),
    nullif(left(coalesce(p_codigo,''),120),''),
    nullif(left(coalesce(p_mensagem,''),300),''),
    nullif(left(coalesce(p_permissao,''),30),''),
    nullif(left(coalesce(p_navegador,''),500),'')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

